"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[847],{3447:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a store\\n\\nThee store holds every tracked target, so the render clock and the `PreRender` connection. One store per client is enough for most games.\\n\\n```lua\\nlocal store = Nerp.new(20, \\"SMOOTH\\")\\n```","params":[{"name":"rate","desc":"Sample spacing in seconds. Default to 20 when nil","lua_type":"number"},{"name":"delay","desc":"`\\"SMOOTH\\"` or `\\"LOW_LATENCY\\"`. Defaults to `\\"SMOOTH\\"`","lua_type":"DelayPreset"}],"returns":[{"desc":"","lua_type":"Store"}],"function_type":"static","source":{"line":61,"path":"src/init.luau"}}],"properties":[{"name":"RATE","desc":"Sample spacing the delay is measured in so 20 matches robloxs physics properly","lua_type":"number","source":{"line":36,"path":"src/init.luau"}},{"name":"DELAY","desc":"Default delay preset. \\"SMOOTH\\" is two samples of intervals","lua_type":"DelayPreset","source":{"line":44,"path":"src/init.luau"}}],"types":[],"name":"Nerp","desc":"Interpolation for server driven transforms\\n\\nThe server puts a `CFrame` with a time and the client buffers it and then plays it back a little late, so 20Hz of updates becomees continuous motion at your framerate.\\n\\nNerp does not own the network, you just send the batch and then you receive it.\\n\\n```lua\\nlocal Nerp = require(game:GetService(\\"ReplicatedStorage\\").Nerp)\\n\\nlocal store = Nerp.new(20, \\"SMOOTH\\") -- OR LOW_LATENCY\\nstore:track(workspace.Crate)\\nstore:start()\\n\\nremote.OnClientEvent:Connect(function(t, cf)\\n    store:feed(workspace.Crate:GetFullName(), { { t = t, cf = cf } })\\nend)\\n```","source":{"line":24,"path":"src/init.luau"}}')}}]);